class Solution {
public:
    bool checkSubarraySum(vector<int>& nums, int k) {
        unordered_map<int, int> seen;
        seen[0] = -1;
        int total = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            total = (total + nums[i]) % k;
            if (seen.count(total)) {
                if (i - seen[total] >= 2) return true;
            } else {
                seen[total] = i;
            }
        }
        return false;
    }
};

class Solution {
    public boolean checkSubarraySum(int[] nums, int k) {
        Map<Integer, Integer> seen = new HashMap<>();
        seen.put(0, -1);
        int total = 0;
        for (int i = 0; i < nums.length; i++) {
            total = (total + nums[i]) % k;
            if (seen.containsKey(total)) {
                if (i - seen.get(total) >= 2) return true;
            } else {
                seen.put(total, i);
            }
        }
        return false;
    }
}

var checkSubarraySum = function(nums, k) {
    const seen = new Map();
    seen.set(0, -1);
    let total = 0;
    for (let i = 0; i < nums.length; i++) {
        total = (total + nums[i]) % k;
        if (seen.has(total)) {
            if (i - seen.get(total) >= 2) return true;
        } else {
            seen.set(total, i);
        }
    }
    return false;
};
